//! Typed reader for the cross-language oracle vectors.
//!
//! `testdata/vectors/*.json` are generated by running real upstream RxDB in Node
//! (`xtask/vectors/`, PLAN.md section 7.2). They are the specification this port
//! is tested against. This crate is the only supported way to read them.
//!
//! # Why this crate exists
//!
//! Before it existed, each consumer lane hand-rolled its own `serde_json::Value`
//! traversal for the same file, which meant several different interpretations of
//! one document and a silent mismatch whenever someone guessed a field name wrong.
//! Field names, nullability and optionality now live in one place.
//!
//! # The rules
//!
//! 1. **Do not edit a vector file.** Vectors are generated data, not code. Editing
//!    one turns the oracle into a record of what we hope is true. Regenerate with
//!    `make vectors` instead.
//! 2. **Do not work around a case you believe is wrong.** If a vector looks wrong,
//!    it is either a generator bug or a genuine upstream behaviour we did not
//!    expect; both need to be known. Report it, with the family, the case index and
//!    the `why` label, so the generator can be fixed and the file regenerated.
//!    Silently skipping a case in a test is the one thing that must not happen:
//!    the corpus then shrinks and the suite keeps passing.
//! 3. **Do not normalise the data.** Structs here use the field names exactly as
//!    Node wrote them, including `$comment`, `_deleted` and `$eq`. Renaming them to
//!    something Rust-idiomatic would let a mismatch hide behind a translation
//!    layer, which is the problem this crate solves.
//!
//! # Usage
//!
//! ```no_run
//! use dxdb_vectors::{schema_hashes, Provenance, VectorFamily, Vectors};
//!
//! let vectors = Vectors::discover();
//! let family = vectors
//!     .load::<schema_hashes::Vectors>(VectorFamily::SchemaHashes)
//!     .expect("the committed vectors decode");
//!
//! // A consumer can assert which oracle it ran against instead of assuming.
//! let provenance: Provenance = family.provenance();
//! assert!(provenance.matches_documented_pin());
//!
//! // `hash` is optional: a schema upstream refused to create has `rejected` instead.
//! for case in family.cases.iter().filter(|c| !c.was_rejected()) {
//!     let hash = case.hash.as_deref().expect("a non-rejected case hashed");
//!     assert_eq!(hash.len(), 64, "sha256 hex");
//! }
//! ```
//!
//! See `crates/dxdb-vectors/README.md` for the copyable version of this and the
//! accessors that replace the hand-rolled schema lookups consumers used to keep.
//!
//! `discover()` resolves `testdata/vectors/` from this crate's own manifest
//! directory, so it works from any consumer crate at any nesting depth.
//!
//! # Unknown fields are rejected
//!
//! Every struct denies unknown fields. If the generator starts emitting a field
//! this crate does not know about, loading fails loudly instead of the field being
//! silently ignored. That keeps "these structs match the JSON" a fact rather than
//! an assumption; it does mean a generator change and a struct change land
//! together, which is the intended coupling.

#![forbid(unsafe_code)]
#![deny(missing_docs)]
#![deny(rustdoc::broken_intra_doc_links)]

mod error;
mod family;
mod loader;

pub use error::VectorError;
pub use family::{
    bulk_write_categorization, error_vectors, index_strings, jsnum, normalised_queries,
    replication_transcripts, schema_hashes, selector_matching,
};
pub use loader::{FamilyFile, Provenance, VectorFamily, Vectors};

/// The case count per family this crate expects to load.
///
/// Committed on purpose. A vector file that is truncated, replaced by an older
/// copy, or generated by a broken generator usually shrinks the corpus rather than
/// producing obviously-invalid JSON, and a suite running against 40 cases instead
/// of 900 still passes. `tests/case_counts.rs` compares every family against this
/// table so that failure is loud.
///
/// Changing a vector family's case count therefore requires updating this table in
/// the same commit. That is deliberate friction: it is the moment to ask whether
/// the change was intended.
pub const EXPECTED_CASE_COUNTS: &[(VectorFamily, usize)] = &[
    (VectorFamily::Jsnum, 304),
    // 900 total = 896 produced + 4 upstream refusals (see `index_strings::Case`).
    (VectorFamily::IndexStrings, 900),
    (VectorFamily::SchemaHashes, 53),
    (VectorFamily::NormalisedQueries, 798),
    (VectorFamily::BulkWriteCategorization, 47),
    // 63 = 60 matching + 3 upstream refusals.
    (VectorFamily::SelectorMatching, 63),
    // Counting snapshots, not transcripts: 13 across 6 transcripts. The batch
    // boundary entry is counted too, since it carries comparable data.
    (VectorFamily::ReplicationTranscripts, 13),
    // Raised cases only: 5 typed + 3 untyped. The 219 declared codes are vocabulary,
    // not cases, and are counted by `declaredCodeCount` inside the file.
    (VectorFamily::ErrorVectors, 8),
];

/// Every family, in the order the generator runs them.
pub const ALL_FAMILIES: &[VectorFamily] = &[
    VectorFamily::Jsnum,
    VectorFamily::IndexStrings,
    VectorFamily::SchemaHashes,
    VectorFamily::NormalisedQueries,
    VectorFamily::BulkWriteCategorization,
    VectorFamily::SelectorMatching,
    VectorFamily::ReplicationTranscripts,
    VectorFamily::ErrorVectors,
];

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_family_has_a_declared_case_count() {
        for family in ALL_FAMILIES {
            assert!(
                EXPECTED_CASE_COUNTS.iter().any(|(f, _)| f == family),
                "family {family:?} is in ALL_FAMILIES but missing from EXPECTED_CASE_COUNTS"
            );
        }
        assert_eq!(
            EXPECTED_CASE_COUNTS.len(),
            ALL_FAMILIES.len(),
            "EXPECTED_CASE_COUNTS and ALL_FAMILIES disagree on how many families there are"
        );
    }

    #[test]
    fn family_file_names_are_unique() {
        let mut names: Vec<&str> = ALL_FAMILIES.iter().map(|f| f.file_stem()).collect();
        names.sort_unstable();
        let count = names.len();
        names.dedup();
        assert_eq!(names.len(), count, "two families share a file name");
    }
}
